/// The nominal kinematic chain from the `ssik` artifact, e.g. as the starting
/// point of `dexhal::math::identify` or for a vendor calibration.
pub fn nominal_chain() -> KinematicChain<DOF> {
    let joints: [ChainJoint; DOF] = core::array::from_fn(|i| ChainJoint {
        origin: Pose::from_row_slice(&JOINT_ORIGINS[i]),
        axis: JOINT_AXES[i],
        offset: 0.0,
    });
    KinematicChain::new(&joints, &Pose::from_row_slice(&FLANGE))
        .expect("nominal chain from the ssik artifact is rigid")
}

/// Rizon10 (7-DOF) model marker.
pub struct Rizon10;

impl ArmModel<DOF, MAX_SOLUTIONS> for Rizon10 {
    const NAME: &'static str = "rizon10";
    const JOINT_LIMITS: [JointLimit; DOF] = [
        Some((-2.8798, 2.8798)),
        Some((-2.7576, 2.7576)),
        Some((-2.8798, 2.8798)),
        Some((-2.7925, 2.7925)),
        Some((-3.0543, 3.0543)),
        Some((-1.4835, 4.6251)),
        Some((-3.0543, 3.0543)),
    ];
    const HAS_DYNAMICS: bool = true;

    #[inline]
    fn flange_fk(q: &[f64; DOF]) -> Pose {
        let t = generated_kinematics::fk(q);
        Pose::from_fn(|r, c| t[r][c])
    }

    #[inline]
    fn flange_jacobian(q: &[f64; DOF]) -> [[f64; DOF]; 6] {
        generated_kinematics::jacobian(q)
    }

    #[inline]
    fn flange_solve(
        target: &Pose,
        max_solutions: Option<usize>,
        q_seed: Option<&[f64; DOF]>,
        respect_limits: bool,
        allow_refinement: bool,
        policy: TolerancePolicy,
        refinement_max_iters: usize,
    ) -> [Option<[f64; DOF]>; MAX_SOLUTIONS] {
        ik_solver::solve(
            target,
            max_solutions,
            q_seed,
            respect_limits,
            allow_refinement,
            policy,
            refinement_max_iters,
        )
    }

    #[inline]
    fn flange_gravity(q: &[f64; DOF], gravity: &[f64; 3]) -> [f64; DOF] {
        generated_dynamics::gravity(q, gravity)
    }

    #[inline]
    fn flange_mass_matrix(q: &[f64; DOF]) -> [[f64; DOF]; DOF] {
        generated_dynamics::mass_matrix(q)
    }

    #[inline]
    fn flange_coriolis(q: &[f64; DOF], qd: &[f64; DOF]) -> [f64; DOF] {
        generated_dynamics::coriolis(q, qd)
    }

    #[inline]
    fn flange_inverse_dynamics(
        q: &[f64; DOF],
        qd: &[f64; DOF],
        qdd: &[f64; DOF],
        gravity: &[f64; 3],
    ) -> [f64; DOF] {
        generated_dynamics::inverse_dynamics(q, qd, qdd, gravity)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use dexhal::math::DEFAULT_TOLERANCE_POLICY;

    /// Deterministic joint vectors inside the joint limits.
    fn sample(k: usize) -> [f64; DOF] {
        core::array::from_fn(|i| {
            let (lo, hi) = match Rizon10::JOINT_LIMITS[i] {
                Some((lo, hi)) => (lo.max(-core::f64::consts::PI), hi.min(core::f64::consts::PI)),
                None => (-core::f64::consts::PI, core::f64::consts::PI),
            };
            let u = ((k * 7 + i * 13) % 17) as f64 / 17.0;
            lo + 0.1 * (hi - lo) + 0.8 * (hi - lo) * u
        })
    }

    #[test]
    fn nominal_chain_matches_generated_kinematics() {
        let chain = nominal_chain();
        for k in 0..16 {
            let q = sample(k);
            let fk = Rizon10::flange_fk(&q);
            assert!((chain.fk(&q) - fk).norm() < 1e-9, "fk mismatch at {q:?}");
            let jac = Rizon10::flange_jacobian(&q);
            let chain_jac = chain.jacobian(&q);
            for r in 0..6 {
                for c in 0..DOF {
                    assert!(libm::fabs(jac[r][c] - chain_jac[r][c]) < 1e-9, "jacobian mismatch at {q:?}");
                }
            }
        }
    }

    #[test]
    fn flange_solve_closes_on_fk_targets() {
        for k in 0..16 {
            let q = sample(k);
            let target = Rizon10::flange_fk(&q);
            let sols = Rizon10::flange_solve(
                &target,
                None,
                Some(&q),
                true,
                false,
                DEFAULT_TOLERANCE_POLICY,
                15,
            );
            let first = sols[0].expect("a reachable in-limit target has a solution");
            assert!((Rizon10::flange_fk(&first) - target).norm() < 1e-6);
            for sol in sols.iter().flatten() {
                assert!((Rizon10::flange_fk(sol) - target).norm() < 1e-6);
            }
        }
    }
}
